-- Seed Data untuk Kelas XII PPLG 1 (22 Siswa + Cita-Cita + Data Kelas)
insert into class_info (id, name, tagline, description, homeroom_teacher, school_year, socials)
values (
  1,
  'XII PPLG 1',
  'Merakit baris kode, gim interaktif, dan masa depan impian dari bangku SMK.',
  'Rumah digital resmi kelas XII Pengembangan Perangkat Lunak dan Gim 1. Tempat kumpul 22 engineer muda: dari jadwal praktikum lab, papan tulis cita-cita 3D, antrean deadline, laporan kas transparan, sampai buku tamu.',
  'Bpk. Hendra Wijaya, S.Kom., M.T.',
  '2026 / 2027',
  '{"instagram": "https://instagram.com/xiipplg1.official", "github": "https://github.com/xii-pplg-1", "discord": "https://discord.gg/xiipplg1"}'::jsonb
) on conflict (id) do update set
  name = excluded.name,
  tagline = excluded.tagline,
  description = excluded.description,
  homeroom_teacher = excluded.homeroom_teacher,
  school_year = excluded.school_year;

insert into students (
  roll_no, name, role, bio, tags, tone,
  dream_title, dream_reason, dream_description, dream_paper_color, sort_order
) values
(1, 'Siswa 01', 'Ketua Kelas', 'Koordinator utama kelas dan arsitek sistem backend. Kalau server lab down, orang pertama yang dicari.', ARRAY['Backend', 'DevOps', 'Next.js'], 1, 'Principal Cloud & Distributed Systems Architect', 'Sering lihat layanan sekolah tumbang waktu trafik ujian naik, jadi tertantang bikin infrastruktur yang tahan banting.', 'Mendalami Kubernetes, Go, dan arsitektur multi-region sambil membangun platform cloud lokal untuk sekolah.', '#D3E6F3', 1),
(2, 'Siswa 02', 'Wakil Ketua', 'Menjaga ritme kelas tetap kondusif dan hobi bikin prototipe mekanik gim 3D di waktu luang.', ARRAY['Game Dev', 'Three.js', 'C#'], 2, 'Lead Gameplay & Physics Programmer', 'Dari kecil penasaran gimana mekanik ayunan dan tabrakan di gim 3D bisa terasa sangat memuaskan.', 'Merilis gim indie 3D bersama teman kelas di Steam dan mendalami C++ serta custom shader di engine modern.', '#DDEBD6', 2),
(3, 'Siswa 03', 'Sekretaris I', 'Dokumentasi rapi dari presensi harian sampai notulensi rapat projek pameran akhir tahun.', ARRAY['UI/UX', 'Figma', 'Docs'], 3, 'Staff Product Designer & UX Researcher', 'Aplikasi canggih sering gagal dipakai gara-gara tampilannya membingungkan pengguna awam.', 'Membangun sistem desain yang inklusif, ramah aksesibilitas, dan punya dokumentasi sejelas kristal.', '#DDD6F2', 3),
(4, 'Siswa 04', 'Sekretaris II', 'Pengatur jadwal piket dan pengingat deadline tugas produktif sebelum jam 23:59.', ARRAY['Frontend', 'Motion', 'Tailwind'], 4, 'Creative Frontend & Design Engineer', 'Suka banget sama perpaduan antara kode presisi dan animasi mikro yang bikin pengguna tersenyum.', 'Menguasai WebGL, animasi spring interaktif, dan berkontribusi ke pustaka UI open-source internasional.', '#E6DAF0', 4),
(5, 'Siswa 05', 'Bendahara I', 'Penjaga transparansi kas kelas sampai rupiah terakhir. Anti selisih di spreadsheet.', ARRAY['Data', 'PostgreSQL', 'FinTech'], 5, 'FinTech Data & Reliability Engineer', 'Ngurus kas kelas bikin sadar betapa pentingnya pencatatan keuangan yang akurat, cepat, dan transparan.', 'Merancang sistem buku besar (ledger) terdistribusi yang aman dari duplikasi transaksi dan mudah diaudit.', '#F9E3CB', 5),
(6, 'Siswa 06', 'Bendahara II', 'Partner audit kas bulanan dan kolektor dana konsumsi saat praktikum panjang.', ARRAY['Fullstack', 'Supabase', 'TypeScript'], 1, 'Fullstack SaaS Founder', 'Ingin membantu UMKM di sekitar kota supaya punya sistem kasir dan inventaris yang semudah aplikasi chat.', 'Membangun startup SaaS mikro selepas lulus SMK dengan stack Next.js, PostgreSQL, dan pembayaran otomatis.', '#CFEBE2', 6),
(7, 'Siswa 07', 'Koordinator Lab', 'Memastikan proyektor, kabel LAN, dan PC lab selalu siap sebelum bel masuk berbunyi.', ARRAY['IoT', 'Networking', 'Linux'], 2, 'Embedded Systems & IoT Engineer', 'Paling senang kalau baris kode yang ditulis bisa menggerakkan perangkat keras nyata di dunia fisik.', 'Mengembangkan perangkat sensor pintar hemat daya berbasis Rust dan ESP32 untuk otomasi gedung sekolah.', '#DDEBD6', 7),
(8, 'Siswa 08', 'Koordinator Kreatif', 'Pengarah visual galeri kelas, dokumentasi kegiatan, dan desain merchandise angkatan.', ARRAY['Creative Dev', 'WebGL', 'Shader'], 3, 'Technical Artist & Shader Programmer', 'Kagum sama cara matematika dan trigonometri bisa berubah jadi efek air, kabut, dan cahaya di layar.', 'Bekerja di studio gim atau agensi kreatif global sebagai jembatan antara tim 3D artist dan engine programmer.', '#D3E6F3', 8),
(9, 'Siswa 09', 'Anggota', 'Spesialis optimasi query database dan arsitektur REST API untuk aplikasi sekolah.', ARRAY['Backend', 'Go', 'Docker'], 4, 'Database Internals & Backend Engineer', 'Merasa puas luar biasa setiap kali berhasil memangkas waktu query dari 2 detik menjadi 8 milidetik.', 'Mempelajari struktur penyimpanan B-Tree, indexing lanjutan, dan membangun layanan API berkecepatan tinggi.', '#DDD6F2', 9),
(10, 'Siswa 10', 'Anggota', 'Pecinta pixel art dan perancang level untuk projek gim platformer 2D kelas.', ARRAY['Game Dev', 'Godot', 'Pixel Art'], 5, 'Indie Game Director & Level Designer', 'Ingin menyampaikan cerita petualangan khas Nusantara lewat mekanik level gim yang menantang tapi adil.', 'Menyelesaikan trilogi gim platformer pixel-art di Godot Engine dan membawanya ke pameran gim Asia Tenggara.', '#F9E3CB', 10),
(11, 'Siswa 11', 'Anggota', 'Eksplorator animasi antarmuka dan micro-interaction yang bikin web terasa hidup.', ARRAY['Frontend', 'GSAP', 'React'], 1, 'Interactive WebGL & Motion Architect', 'Website yang berkesan itu seperti ruang pameran interaktif, bukan sekadar brosur teks yang digulir.', 'Menciptakan pengalaman web pemenang penghargaan yang tetap ringan dijalankan di perangkat spesifikasi rendah.', '#E6DAF0', 11),
(12, 'Siswa 12', 'Anggota', 'Fokus di pengembangan aplikasi mobile lintas platform dan integrasi sensor.', ARRAY['Mobile Dev', 'Flutter', 'Kotlin'], 2, 'Lead Mobile Platform Engineer', 'Hampir semua orang mengakses internet lewat ponsel, jadi aplikasi mobile harus super responsif dan hemat baterai.', 'Mendalami arsitektur native Kotlin & Flutter serta membangun aplikasi kesehatan offline-first untuk daerah pelosok.', '#CFEBE2', 12),
(13, 'Siswa 13', 'Anggota', 'Suka mengulik keamanan aplikasi web, CTF, dan audit autentikasi sebelum rilis.', ARRAY['Security', 'Pentest', 'Auth'], 3, ' Offensive Security & AppSec Researcher', 'Sering ikut kompetisi Capture The Flag (CTF) dan sadar banyak sistem penting yang masih punya celah dasar.', 'Menjadi bug hunter profesional dan konsultan keamanan aplikasi yang melindungi data jutaan pengguna.', '#DDEBD6', 13),
(14, 'Siswa 14', 'Anggota', 'Perancang karakter 3D low-poly dan environment artist untuk pameran karya PPLG.', ARRAY['3D Art', 'Blender', 'Shader'], 4, '3D Environment & World Building Artist', 'Dari hobi bikin sketsa bangunan di buku tulis, sekarang ketagihan menghidupkan dunia 3D di Blender.', 'Merancang aset lingkungan 3D bergaya stylized yang dioptimalkan untuk gim konsol dan WebXR.', '#D3E6F3', 14),
(15, 'Siswa 15', 'Anggota', 'Pengembang bot otomasi pengingat jadwal dan integrasi webhook kelas.', ARRAY['Backend', 'Node.js', 'API'], 5, 'Platform Automation & Workflow Engineer', 'Malas melakukan pekerjaan berulang dua kali kalau bisa diotomasi dengan skrip dalam lima menit.', 'Membangun ekosistem bot dan pipeline integrasi API yang menghemat ribuan jam kerja tim rekayasa.', '#DDD6F2', 15),
(16, 'Siswa 16', 'Anggota', 'Peneliti aksesibilitas web dan performa Lighthouse agar aplikasi nyaman di semua perangkat.', ARRAY['Frontend', 'A11y', 'Testing'], 1, 'Web Performance & Accessibility Lead', 'Teknologi yang baik harus bisa diakses siapa saja, termasuk pengguna pembaca layar dan koneksi lambat.', 'Menjadi spesialis audit Core Web Vitals dan standar WCAG di perusahaan teknologi berskala besar.', '#E6DAF0', 16),
(17, 'Siswa 17', 'Anggota', 'Peracik audio sintetis dan sound effect prosedural untuk projek gim kelas.', ARRAY['Game Dev', 'WebAudio', 'SFX'], 2, 'Interactive Audio & DSP Programmer', 'Suara langkah kaki dan denting tombol yang pas bikin dunia virtual terasa sepuluh kali lebih nyata.', 'Mengembangkan engine audio adaptif berbasis WebAudio dan C++ yang berubah dinamis mengikuti suasana gim.', '#F9E3CB', 17),
(18, 'Siswa 18', 'Anggota', 'Antusias machine learning terapan dan eksperimen computer vision di browser.', ARRAY['AI', 'Python', 'WebGPU'], 3, 'Applied AI & Edge Computing Engineer', 'Terpukau melihat model visi komputer bisa jalan langsung di browser tanpa harus kirim data ke server.', 'Riset optimasi model AI ringan berbasis WebGPU untuk membantu deteksi dini di bidang pendidikan dan pertanian.', '#CFEBE2', 18),
(19, 'Siswa 19', 'Anggota', 'Desainer sistem komponen glassmorphism dan kurator tipografi projek kelas.', ARRAY['UI/UX', 'Design System', 'CSS'], 4, 'Design Systems Architect', 'Kekacauan warna dan spasi saat kerja kelompok bikin aku jatuh cinta pada keteraturan design token.', 'Memimpin tim Design System yang menyatukan bahasa visual antara desainer Figma dan engineer produksi.', '#DDEBD6', 19),
(20, 'Siswa 20', 'Anggota', 'Penyusun algoritma fisika dan sistem partikel di engine gim berbasis web.', ARRAY['Game Dev', 'Three.js', 'Math'], 5, 'Simulation & Graphics Engine Programmer', 'Rumus fisika dan aljabar linear di kelas jadi jauh lebih seru waktu langsung dipraktekkan ke simulasi partikel.', 'Merancang engine simulasi fisika real-time untuk edukasi sains interaktif dan gim sandbox.', '#D3E6F3', 20),
(21, 'Siswa 21', 'Anggota', 'Pengelola repositori Git kelas, tukang beresin merge conflict menjelang presentasi.', ARRAY['DevOps', 'CI/CD', 'Fullstack'], 1, 'Site Reliability & DevSecOps Lead', 'Senang saat melihat pipeline deployment hijau semua dan rilis berjalan mulus tanpa downtime sedikit pun.', 'Membangun infrastruktur CI/CD otomatis yang aman dan cepat untuk tim pengembang lintas negara.', '#DDD6F2', 21),
(22, 'Siswa 22', 'Anggota', 'Eksplorator desain generatif, seni algoritmik, dan visualisasi data interaktif.', ARRAY['Creative Dev', 'Generative Art', 'UI/UX'], 2, 'Creative Technologist & Interactive Media Artist', 'Ingin menggabungkan logika pemrograman dengan instalasi seni interaktif di ruang publik.', 'Mendirikan studio kreatif yang memproduksi instalasi visual 3D interaktif dan museum digital.', '#F9E3CB', 22)
on conflict (roll_no) do update set
  dream_title = excluded.dream_title,
  dream_reason = excluded.dream_reason,
  dream_description = excluded.dream_description,
  dream_paper_color = excluded.dream_paper_color;
